# (chữ Hán hiển thị, dịch, ghi chú[, lời đọc tiếng Trung: số viết bằng chữ Hán, bỏ ngoặc kép])
P = [
    ("我们一直以为世界纪录就是要不断被打破，但国际田联公布的各项比赛成绩却告诉我们，多数世界纪录都是在20世纪90年代创造的。",
     "Chúng ta vẫn luôn cho rằng kỷ lục thế giới là để không ngừng bị phá, nhưng thành tích các môn thi đấu do Liên đoàn Điền kinh Quốc tế công bố lại cho chúng ta biết: phần lớn kỷ lục thế giới đều được lập vào những năm 90 của thế kỷ 20.",
     ["一直以为 là vẫn luôn tưởng rằng, thường hàm ý điều mình tưởng là sai. 国际田联 là cách gọi tắt của 国际田径联合会, Liên đoàn Điền kinh Quốc tế, theo chú thích của sách.",
      "Cách đọc số: 二十世纪九十年代 là thập niên chín mươi của thế kỷ hai mươi. Nghĩa là từ đó đến nay, rất nhiều kỷ lục vẫn chưa bị phá."],
     "我们一直以为世界纪录就是要不断被打破，但国际田联公布的各项比赛成绩却告诉我们，多数世界纪录都是在二十世纪九十年代创造的。"),
    ("此外，更有人引用《每日电讯报》的说法称：截至2060年，人类可能不会再创造体坛新纪录。",
     "Ngoài ra, còn có người trích dẫn tờ Điện tín hằng ngày (The Daily Telegraph) cho rằng: tính đến năm 2060, có thể loài người sẽ không lập thêm được kỷ lục thể thao mới nào nữa.",
     ["更有人 là thậm chí còn có người, mức độ mạnh hơn. 的说法称 ở đây là theo cách nói, cho rằng. 截至二零六零年 là tính đến năm hai không sáu mươi.",
      "体坛 là làng thể thao, giới thể thao. 创造新纪录 là lập kỷ lục mới. Chú ý 纪录 trong 世界纪录 viết với bộ mịch, nghĩa là kỷ lục."],
     "此外，更有人引用每日电讯报的说法称：截至二零六零年，人类可能不会再创造体坛新纪录。"),
    ("一个人的体能究竟有多大？人们在力争打破世界纪录的同时，不禁会对自己的身体产生疑问。",
     "Thể lực của một con người rốt cuộc lớn đến mức nào? Con người, trong khi ra sức phá kỷ lục thế giới, không khỏi nảy sinh nghi vấn về chính cơ thể mình.",
     ["体能 là thể lực, sức lực của cơ thể. 究竟 là rốt cuộc, dùng trong câu hỏi để nhấn mạnh.",
      "在……的同时 là đồng thời với…, trong khi…. 不禁 là không kìm được, không khỏi, đọc là bùjīn."]),
    ("比如说，100米短跑最快需要几秒？这不是一个简单的谁拿冠军、谁拿亚军、谁拿季军的问题，这是对人类体能极限的追问。",
     "Ví dụ như, chạy 100 mét nhanh nhất cần mấy giây? Đây không phải là câu hỏi đơn giản ai giành vô địch, ai giành hạng nhì, ai giành hạng ba, mà là sự truy vấn về giới hạn thể lực của loài người.",
     ["一百米短跑 là chạy cự ly ngắn một trăm mét. Ba vế 谁拿冠军、谁拿亚军、谁拿季军 xếp liền nhau tạo nhịp điệu cho câu văn.",
      "这不是……，这是…… là đây không phải…, mà là…. 追问 là hỏi dồn, truy hỏi đến cùng."],
     "比如说，一百米短跑最快需要几秒？这不是一个简单的谁拿冠军、谁拿亚军、谁拿季军的问题，这是对人类体能极限的追问。"),
    ("有专家认为，人类跑100米速度的极限应该是10.42秒，再考虑一般跑到80米才能达到全速，人类可能达到的最快速度大约为11.96秒。",
     "Có chuyên gia cho rằng, giới hạn tốc độ chạy 100 mét của con người đáng lẽ là 10,42 giây; lại xét đến việc thường phải chạy đến mét thứ 80 mới đạt tốc độ tối đa, thì tốc độ nhanh nhất con người có thể đạt được vào khoảng 11,96 giây.",
     ["Cách đọc số: 十点四二秒 là mười phẩy bốn hai giây; 十一点九六秒 là mười một phẩy chín sáu giây. Các con số này được ghi đúng như trong sách.",
      "再考虑…… là lại xét thêm…. 全速 là tốc độ tối đa. 大约为 là vào khoảng, nghĩa giống 大约是."],
     "有专家认为，人类跑一百米速度的极限应该是十点四二秒，再考虑一般跑到八十米才能达到全速，人类可能达到的最快速度大约为十一点九六秒。"),
    ("然而，在那条狭窄的跑道上，任性的牙买加田径比赛选手博尔特简直就不把世界纪录放在眼里！",
     "Thế nhưng, trên đường chạy chật hẹp ấy, vận động viên điền kinh người Jamaica ngang tàng Usain Bolt quả thực chẳng coi kỷ lục thế giới ra gì!",
     ["然而 là thế nhưng, đánh dấu bước ngoặt: chuyên gia nói có giới hạn, nhưng Bolt lại liên tục phá kỷ lục. 牙买加 là Jamaica, 博尔特 là Usain Bolt.",
      "简直 là quả thực, gần như là. 不把某某放在眼里 là không coi… ra gì, đây là điểm ngữ pháp thứ nhất của bài."]),
    ("2008年6月1日，在美国纽约锐步大奖赛上，他以9.72秒的成绩获得100米短跑冠军，打破了同胞鲍威尔保持的9.74秒的世界纪录；",
     "Ngày 1 tháng 6 năm 2008, tại giải Grand Prix Reebok ở New York, Mỹ, anh đã giành chức vô địch chạy 100 mét với thành tích 9,72 giây, phá kỷ lục thế giới 9,74 giây do người đồng hương Asafa Powell nắm giữ;",
     ["以……的成绩 là với thành tích…. 保持纪录 là giữ kỷ lục. 纽约 là New York, 锐步大奖赛 là giải Grand Prix Reebok, 鲍威尔 là Asafa Powell.",
      "Cách đọc: 二零零八年六月一日; 九点七二秒 là chín phẩy bảy hai giây; 九点七四秒 là chín phẩy bảy bốn giây. Năm đọc từng chữ số, còn số thập phân thì dùng chữ 点."],
     "二零零八年六月一日，在美国纽约锐步大奖赛上，他以九点七二秒的成绩获得一百米短跑冠军，打破了同胞鲍威尔保持的九点七四秒的世界纪录；"),
    ("2008年8月16日北京奥运会百米决赛电视直播中，摇动的旗帜汇成了沸腾的海洋，他以9.69秒的成绩再次刷新世界纪录，领先亚军0.2秒。",
     "Ngày 16 tháng 8 năm 2008, trong buổi truyền hình trực tiếp trận chung kết 100 mét tại Thế vận hội Bắc Kinh, những lá cờ phất phới hợp thành một biển người sôi sục; anh đã lập lại kỷ lục thế giới với thành tích 9,69 giây, về trước người hạng nhì 0,2 giây.",
     ["奥运会 là Thế vận hội Olympic. 百米决赛 là trận chung kết một trăm mét. 汇成了沸腾的海洋 là hợp thành biển người sôi sục, một hình ảnh ẩn dụ rất đẹp.",
      "刷新纪录 là phá kỷ lục, nghĩa đen là làm mới kỷ lục. Cách đọc: 九点六九秒 là chín phẩy sáu chín giây; 零点二秒 là không phẩy hai giây."],
     "二零零八年八月十六日北京奥运会百米决赛电视直播中，摇动的旗帜汇成了沸腾的海洋，他以九点六九秒的成绩再次刷新世界纪录，领先亚军零点二秒。"),
    ("振奋之余人们不禁再次追问——人体运动到底有没有极限？",
     "Sau niềm phấn khích, người ta không khỏi một lần nữa đặt câu hỏi: vận động của cơ thể con người rốt cuộc có giới hạn hay không?",
     ["振奋 là phấn chấn, phấn khích. ……之余 là sau khi…, ngoài…ra, cách nói văn viết: 振奋之余, sau niềm phấn khích.",
      "Dấu gạch ngang dài dẫn ra câu hỏi trọng tâm của cả bài: 人体运动到底有没有极限？"],
     "振奋之余人们不禁再次追问，人体运动到底有没有极限？"),
    ("有研究者分解了博尔特取得9.72秒成绩的那次比赛动作，并利用公式做了精密计算，结论是：他是从静止状态开跑的，9.72秒还包括了加速的时间，",
     "Có nhà nghiên cứu đã phân tích từng động tác trong lần thi đấu Bolt đạt thành tích 9,72 giây, và dùng công thức để tính toán chính xác. Kết luận là: anh xuất phát từ trạng thái đứng yên, 9,72 giây đó còn bao gồm cả thời gian tăng tốc,",
     ["分解动作 là phân tích từng động tác. 利用公式 là sử dụng công thức. 并 ở đây là và, đồng thời.",
      "从静止状态开跑 là xuất phát từ trạng thái đứng yên, chữ 静 ta vừa học ở phần khởi động. 加速 là tăng tốc."],
     "有研究者分解了博尔特取得九点七二秒成绩的那次比赛动作，并利用公式做了精密计算，结论是：他是从静止状态开跑的，九点七二秒还包括了加速的时间，"),
    ("如果他跑200米，那么，第二个100米会比第一个100米快，因为没有起跑的过程。",
     "nếu anh chạy 200 mét, thì 100 mét thứ hai sẽ nhanh hơn 100 mét thứ nhất, vì không có giai đoạn xuất phát.",
     ["如果……那么…… là nếu… thì…. 起跑 là xuất phát, khởi động chạy.",
      "Cách đọc: 二百米 hoặc 两百米 là hai trăm mét; 第二个一百米 là một trăm mét thứ hai. Ý nói tốc độ thật của Bolt còn nhanh hơn thành tích ghi trên bảng."],
     "如果他跑二百米，那么，第二个一百米会比第一个一百米快，因为没有起跑的过程。"),
    ("数据相差如此悬殊，我们到底信谁？飞人博尔特创造的奇迹怎么解释？我们还能迷信专家吗？",
     "Số liệu chênh lệch lớn đến thế, rốt cuộc chúng ta tin ai? Kỳ tích mà người bay Bolt tạo ra giải thích thế nào? Chúng ta còn có thể tin mù quáng vào chuyên gia được nữa không?",
     ["相差如此悬殊 là chênh lệch lớn đến thế. 飞人 là người bay, biệt danh của vận động viên chạy cực nhanh.",
      "Ba câu hỏi liên tiếp thể hiện sự băn khoăn của dư luận, tạo cao trào cho bài viết. 迷信 ở đây là động từ, tin mù quáng."]),
    ("一时舆论哗然，质疑不断，专家、学者、网民纷纷自发掀起人体极限的讨论。",
     "Nhất thời dư luận xôn xao, nghi vấn không ngớt; các chuyên gia, học giả, cư dân mạng đều tự phát dấy lên cuộc thảo luận về giới hạn của cơ thể con người.",
     ["一时 là nhất thời, trong một lúc. 哗然 là ồn ào xôn xao, 舆论哗然 là dư luận xôn xao. 质疑 là đặt nghi vấn.",
      "纷纷 là lần lượt, rối rít, nhiều người cùng làm. 网民 là cư dân mạng. 掀起……的讨论 là dấy lên cuộc thảo luận về…."]),
    ("有人说，空洞的结论没有说服力，我们还是看看人体结构吧。运动员向前跑的动力大部分由股四头肌提供，股四头肌腱与膝盖连接，运动员才可以加速，",
     "Có người nói, kết luận sáo rỗng thì không có sức thuyết phục, chúng ta hãy xem cấu tạo cơ thể người thì hơn. Động lực để vận động viên chạy về phía trước phần lớn do cơ tứ đầu đùi cung cấp; gân cơ tứ đầu đùi nối với đầu gối, nhờ vậy vận động viên mới có thể tăng tốc,",
     ["还是……吧 là tốt hơn hết là…, dùng để đưa ra lời đề nghị sau khi cân nhắc. 说服力 là sức thuyết phục.",
      "股四头肌 là cơ tứ đầu đùi, nhóm cơ lớn ở mặt trước đùi. 肌腱 là gân cơ. 由……提供 là do… cung cấp."]),
    ("这一结构也成为了运动员加速的制约因素，原理就是，超越极限的速度需要的力量足以造成股四头肌腱和膝盖间的连接点撕裂。",
     "cấu tạo này cũng trở thành yếu tố hạn chế việc tăng tốc của vận động viên. Nguyên lý là: lực cần thiết cho một tốc độ vượt quá giới hạn đủ để làm rách chỗ nối giữa gân cơ tứ đầu đùi và đầu gối.",
     ["这一结构 là cấu tạo này, cách nói văn viết. 制约因素 là yếu tố hạn chế. 原理就是 là nguyên lý chính là.",
      "足以 là đủ để. 造成……撕裂 là gây ra rách, đứt. Nói cách khác: nếu chạy nhanh hơn giới hạn, cơ thể sẽ tự làm mình bị thương."]),
    ("人体结构是确定的，人体活动当然也有一定的范围，科学就是这么冷酷。",
     "Cấu tạo cơ thể người là cố định, nên hoạt động của cơ thể đương nhiên cũng có phạm vi nhất định. Khoa học lạnh lùng như thế đấy.",
     ["确定的 là đã xác định, cố định, không thay đổi. 一定的范围 là phạm vi nhất định.",
      "科学就是这么冷酷 là một câu kết ngắn gọn, mạnh mẽ cho lập luận từ cấu tạo cơ thể: khoa học chỉ nói sự thật, không chiều lòng ai."]),
    ("也有人从运动医学和心理学角度出发，其观点也不无道理。跑步看起来是用腿，其实要动员全身的力量，牵扯到各个器官。",
     "Cũng có người xuất phát từ góc độ y học thể thao và tâm lý học, quan điểm của họ cũng không phải là không có lý. Chạy bộ trông thì như chỉ dùng chân, thực ra phải huy động sức lực toàn thân, kéo theo mọi cơ quan.",
     ["从……角度出发 là xuất phát từ góc độ…. 其 là đại từ văn viết, ở đây bằng 他们的. 不无道理 là không phải không có lý, tức là cũng có lý, đây là điểm ngữ pháp thứ hai.",
      "看起来……，其实…… là trông thì…, thực ra…. Câu 其观点也不无道理 là câu tổng; các câu sau là phần phân tích cụ thể. Đây chính là kết cấu tổng phân ta học ở cuối bài."]),
    ("拿胸膛里的心脏来说，它管辖着全身，如果它出了故障，腿再快也不管用。",
     "Lấy trái tim trong lồng ngực mà nói, nó cai quản toàn thân; nếu nó gặp trục trặc, chân có nhanh đến mấy cũng vô dụng.",
     ["拿……来说 là lấy… mà nói, dùng để đưa ra ví dụ. 管辖着全身 là cai quản toàn thân, biện pháp nhân hóa.",
      "再……也…… là dù… đến mấy cũng…: 腿再快也不管用. 不管用 là không có tác dụng, vô dụng."]),
    ("人进入运动状态后，心率加快，运动时最高心率＝（220－年龄）次/分。运动时的心率应在一定范围内，低限一般是最高心率的60%，高限一般是最高心率的85%。",
     "Sau khi con người bước vào trạng thái vận động, nhịp tim tăng nhanh; nhịp tim tối đa khi vận động bằng 220 trừ đi số tuổi, tính theo số lần mỗi phút. Nhịp tim khi vận động nên nằm trong một phạm vi nhất định: mức thấp thường là 60% nhịp tim tối đa, mức cao thường là 85% nhịp tim tối đa.",
     ["心率 là nhịp tim. Công thức đọc là: 最高心率等于二百二十减去年龄，单位是次每分钟. Nghĩa là nhịp tim tối đa bằng hai trăm hai mươi trừ đi số tuổi.",
      "低限 là mức thấp, 高限 là mức cao. 百分之六十 là sáu mươi phần trăm, 百分之八十五 là tám mươi lăm phần trăm. Nhớ: tiếng Trung nói 百分之 trước, rồi mới đến con số."],
     "人进入运动状态后，心率加快，运动时最高心率等于二百二十减去年龄，单位是次每分钟。运动时的心率应在一定范围内，低限一般是最高心率的百分之六十，高限一般是最高心率的百分之八十五。"),
    ("如一名40岁的人，运动时的心率应保持在每分钟108－150次左右，严禁超过心率的极限值，否则会因供血不足发生猝死。",
     "Ví dụ một người 40 tuổi, khi vận động nhịp tim nên giữ ở khoảng 108 đến 150 lần mỗi phút, nghiêm cấm vượt quá giá trị giới hạn của nhịp tim, nếu không sẽ có thể đột tử do thiếu máu cung cấp.",
     ["如 ở đây là ví dụ như. 保持在……左右 là giữ ở khoảng…. 严禁 là nghiêm cấm, 否则 là nếu không thì. 供血不足 là cung cấp máu không đủ.",
      "Các bạn thử tính nhé: hai trăm hai mươi trừ bốn mươi là một trăm tám mươi; sáu mươi phần trăm là một trăm lẻ tám, tám mươi lăm phần trăm khoảng một trăm năm mươi. Cách đọc: 每分钟一百零八到一百五十次."],
     "如一名四十岁的人，运动时的心率应保持在每分钟一百零八到一百五十次左右，严禁超过心率的极限值，否则会因供血不足发生猝死。"),
    ("每个人的运动极限都不同，长期正规科学的训练，多次接近实战性的“演习”，可以让自己越来越接近极限。",
     "Giới hạn vận động của mỗi người đều khác nhau. Tập luyện lâu dài, bài bản và khoa học, cộng với nhiều lần diễn tập gần giống thực chiến, có thể giúp bản thân ngày càng tiến gần đến giới hạn.",
     ["长期正规科学的训练 là tập luyện lâu dài, chính quy, khoa học. 实战性 là tính thực chiến, sát với thi đấu thật.",
      "越来越接近极限 là ngày càng tiến gần giới hạn. Chú ý: đến gần giới hạn, chứ không nói là vượt qua giới hạn."]),
    ("人的心理因素弹性很大，积极的精神状态可以激发身体潜能，从而让运动员在竞赛中超水平发挥。",
     "Yếu tố tâm lý của con người có độ co giãn rất lớn: trạng thái tinh thần tích cực có thể khơi dậy tiềm năng của cơ thể, từ đó giúp vận động viên thi đấu vượt cả trình độ thường ngày.",
     ["弹性很大 là co giãn rất lớn, tức là có thể thay đổi nhiều. 激发潜能 là khơi dậy tiềm năng.",
      "从而 là từ đó, nhờ đó, nối kết quả. 超水平发挥 là phát huy vượt trình độ bình thường, thi đấu xuất thần."]),
    ("体能只有60%是与生俱来的，其余40%要通过训练等外界影响去发掘。故而，体能、心理素质好的运动员，会成为优先选拔的对象。",
     "Thể lực chỉ có 60% là bẩm sinh, 40% còn lại phải thông qua những tác động bên ngoài như tập luyện để khai thác. Vì thế, những vận động viên có thể lực và tố chất tâm lý tốt sẽ trở thành đối tượng được ưu tiên tuyển chọn.",
     ["与生俱来 là sinh ra đã có, bẩm sinh. 其余 là phần còn lại. 发掘 là đào bới, khai thác. Cách đọc: 百分之六十, 百分之四十.",
      "故而 là vì thế, cho nên, cách nói văn viết. 心理素质 là tố chất tâm lý, bản lĩnh tâm lý."],
     "体能只有百分之六十是与生俱来的，其余百分之四十要通过训练等外界影响去发掘。故而，体能、心理素质好的运动员，会成为优先选拔的对象。"),
    ("年轻运动员身体资产丰厚，得天独厚的优势就是他们的年龄；老运动员作风过硬，顽强，有志气，不屈服，这些使不少教练员对打破世界纪录依然充满信心。",
     "Vận động viên trẻ có vốn liếng thể chất dồi dào, lợi thế trời cho của họ chính là tuổi trẻ; vận động viên lâu năm thì tác phong vững vàng, ngoan cường, có chí khí, không chịu khuất phục. Những điều này khiến nhiều huấn luyện viên vẫn tràn đầy niềm tin vào việc phá kỷ lục thế giới.",
     ["Câu dùng phép đối: 年轻运动员 đối với 老运动员, mỗi bên có ưu thế riêng. 丰厚 là dồi dào. 过硬 là vững vàng, chịu được thử thách.",
      "这些使…… là những điều này khiến…. 依然 là vẫn, vẫn như cũ. 充满信心 là tràn đầy niềm tin."]),
    ("体育界有种说法：“运动员选对了，就成功了一半；通过训练让运动员的超能力发挥出来，那就是百分之百的成功。”",
     "Giới thể thao có một câu nói: chọn đúng vận động viên là đã thành công một nửa; thông qua tập luyện để phát huy siêu năng lực của vận động viên, thì đó là thành công trăm phần trăm.",
     ["有种说法 là có một cách nói, có câu rằng. 选对了 là chọn đúng rồi, bổ ngữ kết quả 对.",
      "超能力 là siêu năng lực, từ có trong tên bài. 百分之百 là trăm phần trăm, hoàn toàn."]),
    ("优秀的选手和科学训练相辅相成，是通往成功的有效手段。",
     "Vận động viên xuất sắc và tập luyện khoa học bổ trợ cho nhau, đó là con đường hiệu quả dẫn tới thành công.",
     ["相辅相成 là bổ trợ cho nhau. 通往 là dẫn tới, thông tới. 有效手段 là biện pháp hữu hiệu.",
      "Câu này tổng kết hai đoạn trước: một bên là chọn đúng người, một bên là tập luyện khoa học."]),
    ("如今，教练员依托电脑、超高速摄影机等先进装备以及技术分析等手段来指导训练，用新颖的战术思想指导比赛。",
     "Ngày nay, các huấn luyện viên dựa vào những trang thiết bị tiên tiến như máy tính, máy quay tốc độ siêu cao, cùng với các biện pháp như phân tích kỹ thuật để chỉ đạo tập luyện, và dùng tư duy chiến thuật mới mẻ để chỉ đạo thi đấu.",
     ["依托……来…… là dựa vào… để…. 超高速摄影机 là máy quay tốc độ siêu cao. 以及 là cùng với, và, cách nói văn viết.",
      "Hai vế 指导训练 và 指导比赛 song song với nhau: chỉ đạo tập luyện, chỉ đạo thi đấu."]),
    ("谁能顽强地越过人体极限这道“悬崖峭壁”，找到体能的“突破口”，谁就能成为无数竞争者中涌现出来的明星，这也是一个公认的事实。",
     "Ai có thể ngoan cường vượt qua vách đá dựng đứng mang tên giới hạn cơ thể, tìm ra điểm đột phá của thể lực, thì người đó sẽ trở thành ngôi sao nổi lên giữa vô số đối thủ. Đó cũng là một sự thật được mọi người công nhận.",
     ["谁……，谁就…… là ai… thì người đó…, đại từ nghi vấn dùng với nghĩa phiếm chỉ. 道 là lượng từ cho vách núi, cửa ải.",
      "突破口 là điểm đột phá. 公认 là được mọi người công nhận. Bài văn kết thúc bằng một thông điệp lạc quan: giới hạn vẫn có thể bị thách thức."]),
]

add("bullets", chapter="Bài khóa", section="Bài khóa 课文", title="Phần 2: Bài khóa 人类超能力会改变世界纪录吗", size=42,
    items=["Đọc từng đoạn: nghe tiếng Trung trước (chưa hiện bản dịch)",
           "Sau đó: bản dịch tiếng Việt + giải thích từ ngữ, cấu trúc",
           "Mẹo: tạm dừng, đọc to đoạn văn trước khi nghe giảng",
           "Chú ý cách đọc số: năm, giây, phần trăm"],
    say=["Tiếp theo là phần hai: bài khóa 人类超能力会改变世界纪录吗, dài một nghìn ba trăm sáu mươi bảy chữ. Bài được cải biên từ bài viết cùng tên trên tạp chí 科学画报, Họa báo Khoa học.",
         F(0, "Thầy chia bài thành từng đoạn ngắn. Với mỗi đoạn, các bạn nghe đọc tiếng Trung trước, cố gắng hiểu bằng các từ mới vừa học."),
         F(1, "Sau đó bản dịch tiếng Việt sẽ hiện ra, và thầy giải thích các từ ngữ, cấu trúc quan trọng."),
         F(2, "Nếu muốn luyện đọc, các bạn hãy tạm dừng và tự đọc to đoạn văn trước khi nghe giảng nhé."),
         F(3, "Bài này có rất nhiều con số: năm tháng, số giây, phần trăm. Thầy sẽ hướng dẫn cách đọc từng loại số khi gặp.")])

for i, item in enumerate(P, 1):
    zh, vi, notes = item[:3]
    spoken = item[3] if len(item) > 3 else zh.replace("“", "").replace("”", "")
    zsize = 54 if len(zh) <= 100 else 50
    add("passage", section="Bài khóa 课文", title=f"Bài khóa – đoạn {i}/{len(P)}", zh=zh, vi=vi, zsize=zsize,
        say=[F(0, spoken, cap="(Nghe đọc đoạn văn tiếng Trung)", zr=150),
             F(1, "Dịch nghĩa: " + vi, cap="")] + [F(1, n) for n in notes])

add("bullets", chapter="Tóm tắt nội dung", section="Bài khóa 课文", title="Bố cục bài khóa (theo bài tập 5)", size=36,
    items=["## 1. 对世界纪录的看法 – quan điểm về kỷ lục thế giới",
           "引用《每日电讯报》的说法 · 一个人体能究竟有多大 · 专家认为百米最快速度是多少",
           "## 2. 以博尔特为例说说打破世界纪录的过程",
           "2008.6.1 纽约：9.72秒 · 2008.8.16 北京：9.69秒 · 分解动作，精密计算，结论",
           "## 3. 通过对人体的分析来看人类运动极限",
           "身体结构：动力来源，超越极限速度会撕裂 · 运动医学和心理学：心脏、心率",
           "体能和心理素质 · 优秀选手和科学训练相辅相成"],
    say=["Chúng ta cùng nhìn lại bố cục của cả bài khóa. Bài tập năm trong sách gợi ý bố cục ba phần như sau.",
         F(0, "Phần một: 对世界纪录的看法, quan điểm về kỷ lục thế giới."),
         F(1, "Tác giả trích dẫn tờ Điện tín hằng ngày, đặt câu hỏi 一个人的体能究竟有多大, và nêu ý kiến chuyên gia về tốc độ nhanh nhất khi chạy một trăm mét."),
         F(2, "Phần hai: 以博尔特为例说说打破世界纪录的过程, lấy Bolt làm ví dụ để kể quá trình phá kỷ lục thế giới."),
         F(3, "Ngày một tháng sáu năm hai nghìn không trăm lẻ tám ở New York, anh chạy chín phẩy bảy hai giây; ngày mười sáu tháng tám cùng năm ở Bắc Kinh, anh chạy chín phẩy sáu chín giây. Sau đó các nhà nghiên cứu phân tích động tác, tính toán chính xác và đưa ra kết luận."),
         F(4, "Phần ba: 通过对人体的分析来看人类运动极限, thông qua phân tích cơ thể người để xem giới hạn vận động của loài người."),
         F(5, "Thứ nhất là từ cấu tạo cơ thể: nguồn động lực là cơ tứ đầu đùi, tốc độ vượt giới hạn sẽ làm rách gân. Thứ hai là từ y học thể thao và tâm lý học: trái tim và nhịp tim."),
         F(6, "Thứ ba là thể lực và tố chất tâm lý; và cuối cùng, vận động viên xuất sắc cùng tập luyện khoa học bổ trợ cho nhau. Bố cục này rất có ích khi các bạn viết tóm tắt ở cuối bài.")])

