add("compare", chapter="Phân biệt 顽强 – 坚强", section="Phân biệt từ 词语辨析", title="Phân biệt 顽强 và 坚强",
    common="Giống nhau: đều là tính từ, nghĩa là mạnh mẽ, không thể lay chuyển. Ví dụ: 他很顽强/坚强，没有向困难低过头。",
    cols=[{"head": "顽强",
           "lines": ["(1) Dùng được với nghĩa xấu: 改革受到旧势力的顽强抵抗。",
                     "(2) Tả cả ý chí lẫn hành động, nghĩa là không bỏ cuộc",
                     "Đúng: 他们顽强拼搏，终于赢得了第一名。",
                     "(3) Không dùng làm động từ"]},
          {"head": "坚强",
           "lines": ["(1) Không dùng với nghĩa xấu",
                     "(2) Chỉ tả ý chí, nhấn mạnh sự vững mạnh",
                     "Sai: 他们坚强拼搏。",
                     "(3) Làm động từ làm cho vững: 坚强自己的信心。"]}],
    say=["Tiếp theo là phần phân biệt từ: 顽强 và 坚强. Tiếng Việt thường dịch cả hai là kiên cường, ngoan cường, nên rất dễ dùng lẫn.",
         "Điểm giống nhau: cả hai đều là tính từ, đều có nghĩa mạnh mẽ, không thể lay chuyển, không thể đánh gục. Ví dụ: 他很顽强, hoặc 他很坚强, 没有向困难低过头。 Anh ấy rất kiên cường, chưa từng cúi đầu trước khó khăn.",
         F(0, "Điểm khác thứ nhất. 顽强 dùng được với nghĩa xấu, tức là ngoan cố. Ví dụ: 改革受到旧势力的顽强抵抗。 Cải cách gặp phải sự chống cự ngoan cố của thế lực cũ."),
         F(1, "Còn 坚强 luôn mang nghĩa tốt, không bao giờ dùng với nghĩa xấu."),
         F(0, "Điểm khác thứ hai. 顽强 vừa tả ý chí, vừa tả hành động, mang nghĩa không bỏ cuộc. Ví dụ: 我是越老越顽强，越老越快乐。 Tôi càng già càng kiên cường, càng già càng vui vẻ. Và: 他们顽强拼搏，终于赢得了第一名。 Họ ngoan cường chiến đấu, cuối cùng giành được hạng nhất."),
         F(1, "Còn 坚强 thường chỉ tả ý chí, tinh thần, nhấn mạnh sự vững mạnh của ý chí, không dùng để tả hành động. Vì vậy 他们坚强拼搏 là sai."),
         F(1, "Điểm khác thứ ba. 坚强 còn làm được động từ, nghĩa là làm cho vững vàng. Ví dụ: 丰富自己的知识，坚强自己的信心。 Làm phong phú kiến thức, củng cố niềm tin của bản thân."),
         F(0, "Còn 顽强 không có cách dùng này."),
         "Mẹo nhớ: 顽强 nghiêng về hành động bền bỉ, có thể tốt hoặc xấu; 坚强 nghiêng về ý chí vững vàng, luôn tốt, và còn làm được động từ."])

add("bullets", section="Phân biệt từ 词语辨析", title="Làm thử: Đúng hay sai?", reveal=True, size=36,
    items=["(1) 他以坚强的意志坚持治疗，苦练身体，终于战胜了病魔。",
           "Đáp án: Đúng – 坚强 tả ý chí (意志).",
           "(2) 你一定要顽强自己的意志，做生活的强者。",
           "Đáp án: Sai – 顽强 không làm động từ. Sửa: 坚强自己的意志。",
           "(3) 她在腿部受伤的情况下顽强奋战，终于获得冠军。",
           "Đáp án: Đúng – 顽强 tả hành động (奋战), nghĩa không bỏ cuộc.",
           "(4) 不管敌人怎样坚强抗拒，最终注定要失败。",
           "Đáp án: Sai – nghĩa xấu không dùng 坚强. Sửa: 顽强抗拒。"],
    say=[F(0, "Bây giờ chúng ta làm thử. Câu một: 他以坚强的意志坚持治疗，苦练身体，终于战胜了病魔。 Anh ấy dùng ý chí kiên cường để kiên trì điều trị, chăm chỉ rèn luyện thân thể, cuối cùng đã chiến thắng bệnh tật. Đúng hay sai? Các bạn suy nghĩ nhé."),
         F(1, "Đáp án: đúng. 坚强 ở đây tả ý chí, 坚强的意志, ý chí kiên cường, rất chuẩn."),
         F(2, "Câu hai: 你一定要顽强自己的意志，做生活的强者。 Bạn nhất định phải làm vững ý chí của mình, làm người mạnh mẽ trong cuộc sống."),
         F(3, "Đáp án: sai. Ở đây cần một động từ nghĩa là làm cho vững, mà 顽强 không làm động từ được. Phải sửa thành 坚强自己的意志."),
         F(4, "Câu ba: 她在腿部受伤的情况下顽强奋战，终于获得冠军。 Trong tình trạng bị thương ở chân, cô ấy vẫn ngoan cường chiến đấu, cuối cùng giành chức vô địch."),
         F(5, "Đáp án: đúng. 顽强 tả hành động 奋战, chiến đấu hết mình, mang nghĩa không bỏ cuộc."),
         F(6, "Câu bốn: 不管敌人怎样坚强抗拒，最终注定要失败。 Bất kể kẻ địch chống cự thế nào, cuối cùng nhất định sẽ thất bại."),
         F(7, "Đáp án: sai. Kẻ địch chống cự là việc xấu, mà 坚强 không dùng với nghĩa xấu. Phải sửa thành 顽强抗拒, ngoan cố chống cự.")])

